const $=s=>document.querySelector(s),grid=$('#grid');let all=[],filtered=[],offset=0;
const base=new URL('/assets/visual/',location.origin),safe=value=>{const u=new URL(value,base);return u.origin===location.origin&&u.pathname.startsWith('/assets/visual/')?u.href:null};
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){observer.unobserve(e.target);renderPreview(e.target)}},{rootMargin:'250px'});
async function renderPreview(box){const [key,a]=all.find(([key])=>key===box.dataset.key)||[];if(!a)return;try{const src=safe(a.file);if(!src)throw Error('invalid path');if(a.type==='audio'){const audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.src=src;audio.setAttribute('aria-label',key);box.replaceChildren(audio);return}const img=new Image();img.alt=key;img.src=src;await img.decode();if(a.type==='atlas'&&a.atlas){const r=await fetch(safe(a.atlas)),j=await r.json(),f=j.frames?.['static/south']??Object.values(j.frames??{})[0];if(f&&!f.rotated){const canvas=document.createElement('canvas');canvas.width=canvas.height=128;canvas.setAttribute('aria-label',key);const ctx=canvas.getContext('2d'),rect=f.frame,scale=Math.min(110/rect.w,110/rect.h,2.3);ctx.imageSmoothingEnabled=false;ctx.drawImage(img,rect.x,rect.y,rect.w,rect.h,(128-rect.w*scale)/2,(128-rect.h*scale)/2,rect.w*scale,rect.h*scale);box.replaceChildren(canvas);return}}box.replaceChildren(img)}catch{box.textContent='Không tải được preview; kiểm tra file trong manifest.';box.classList.add('failed')}}
function append(){const batch=filtered.slice(offset,offset+48);for(const[key,a]of batch){const card=document.createElement('article');card.className='card';const box=document.createElement('div');box.className='preview';box.dataset.key=key;box.textContent=a.type==='audio'?'♫':'…';const info=document.createElement('div');info.className='info';const title=document.createElement('h2');title.textContent=key;const meta=document.createElement('small');meta.textContent=[a.type,a.w&&a.h?`${a.w} × ${a.h}`:''].filter(Boolean).join(' · ');const links=document.createElement('div');links.className='files';for(const[label,value]of [['File gốc ↓',a.file],['Atlas JSON ↓',a.atlas]])if(value&&safe(value)){const link=document.createElement('a');link.textContent=label;link.href=safe(value);link.download='';links.append(link)}info.append(title,meta,links);card.append(box,info);grid.append(card);observer.observe(box)}offset+=batch.length;$('#counter').textContent=`${filtered.length.toLocaleString('vi-VN')} / ${all.length.toLocaleString('vi-VN')} tài nguyên`;$('#more').hidden=offset>=filtered.length}
function filter(){observer.disconnect();grid.replaceChildren();offset=0;const term=$('#search').value.trim().toLowerCase(),type=$('#type').value;filtered=all.filter(([k,a])=>(!term||k.toLowerCase().includes(term))&&(type==='all'||a.type===type));append()}
try{const r=await fetch('/assets/visual/index.json');if(!r.ok)throw Error(r.status);all=Object.entries(await r.json());filter();$('#notice').textContent='Ảnh xem trước chỉ tải khi bạn cuộn đến. Âm thanh chỉ tải khi bấm phát. Một nhóm atlas có thể gồm cả ảnh và file JSON.'}catch{$('#counter').textContent='Chưa đọc được manifest';$('#notice').textContent='Chạy npm start trong thư mục bộ tải, không mở trang bằng file://.'}
$('#search').addEventListener('input',filter);$('#type').addEventListener('change',filter);$('#more').onclick=append;
